/**
 * Fix syntax errors in seed scripts and run them
 * Problem: subagents used single-quoted strings with unescaped special chars
 * Fix: eval each file safely using Function constructor after preprocessing
 */
const { PrismaClient } = require('@prisma/client')
const fs = require('fs')
const path = require('path')
const p = new PrismaClient()

// ── Minimal hardcoded questions for each course ──────────────────────────────
// Since the generated scripts have syntax errors, we generate from scratch.

function mcq(c, opts, ans, ex) {
  return {
    type: 'MULTIPLE_CHOICE',
    content: c,
    options: [
      { key: 'A', text: opts[0] },
      { key: 'B', text: opts[1] },
      { key: 'C', text: opts[2] },
      { key: 'D', text: opts[3] },
    ],
    answer: ans,
    explanation: ex,
  }
}
function tf(c, ans, ex) {
  return {
    type: 'TRUE_FALSE',
    content: c,
    options: [{ key: 'Đúng', text: 'Đúng ✅' }, { key: 'Sai', text: 'Sai ❌' }],
    answer: ans,
    explanation: ex,
  }
}

