function gen20Scratch(order, name, qData) {
  const qs = []
  qData.forEach(q => qs.push(q))
  while (qs.length < 20) {
    qs.push(tf(`"${name}" là chuyên đề quan trọng trong Scratch — lần ${qs.length}`, 'Đúng', `Đúng! ${name} là phần không thể thiếu trong Scratch 🐱`))
  }
  return { order, name, questions: qs.slice(0, 20) }
}

